public static void Setup() {
  SetSpeed(14);
}

public static void Tick(int dt) {
  if (GetAngle() < 134) {
    RotateTo(135);
    return;
  }
  if (GetHeight() < 1.5) {
    LiftTo(1.5);
    return;
  }
  if (GetAngle() > 46) {
    RotateTo(45);
    return;
  }
  if (GetHeight() < 2.0) {
    LiftTo(2.0);
  }
}
